class Layout:
    """Resolved view of where the log data, lock and cache live."""

    def __init__(self, root: str, kind: str, archive_root: Optional[str] = None):
        self.root = root
        self.kind = kind  # "dir" or "file"
        # The archive store is a second directory holding sealed segments
        # migrated online. Its location is recorded (and signed) in the
        # manifest; ``None`` means no archive has been registered yet.
        self.archive_root = archive_root
        # The lock is a sibling dotfile in both layouts, so its identity is
        # stable across the file -> segment-store migration.
        normalized = os.path.normpath(root)
        parent = os.path.dirname(normalized) or "."
        self.lock_path = os.path.join(
            parent, "." + os.path.basename(normalized) + LOCK_SUFFIX
        )
        if kind == "dir":
            self.data_dir = root
            self.manifest_path = os.path.join(root, MANIFEST_NAME)
            self.cache_dir = root
            self.cache_name = CACHE_NAME
        else:
            directory = os.path.dirname(root) or "."
            self.data_dir = directory
            self.manifest_path = ""
            self.cache_dir = directory
            self.cache_name = "." + os.path.basename(root) + ".verify-cache"

    @property
    def cache_path(self) -> str:
        return os.path.join(self.cache_dir, self.cache_name)

    def segment_path(self, name: str) -> str:
        return os.path.join(self.data_dir, name)

    def archived_segment_path(self, name: str) -> str:
        if not self.archive_root:
            raise ValueError("log has no registered archive location")
        return os.path.join(self.archive_root, name)

    def with_archive_root(self, archive_root: Optional[str]) -> "Layout":
        """Return a layout clone whose segment resolver knows the archive."""
        if archive_root == self.archive_root:
            return self
        return Layout(self.root, self.kind, archive_root=archive_root)

